import { Geist, Geist_Mono, Montserrat } from "next/font/google";
import React, { type ReactNode } from "react";

import { cn } from "@/lib/utils";

import "@/app/tokens.css";
import "@/app/globals.css";

const GeistSans = Geist({
  subsets: ["latin"],
  variable: "--font-sans",
});

const GeistMono = Geist_Mono({
  subsets: ["latin"],
  variable: "--font-mono",
});

const MontserratSerif = Montserrat({
  subsets: ["latin"],
  variable: "--font-serif",
});

export default function RootLayout({
  children,
}: Readonly<{
  children: ReactNode;
}>) {
  return (
    <html
      lang="en"
      className={cn(
        GeistSans.variable,
        GeistMono.variable,
        MontserratSerif.variable,
        "bg-background text-foreground",
      )}
    >
      <body>
        <main className="mt-16 flex w-full justify-center">
          <div className="container">{children}</div>
        </main>
      </body>
    </html>
  );
}

"use client";

import { NFTComponent } from "@/components/nft/nft-component";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import type React from "react";

// Component content with wallet context
function NFTContent() {
  return (
    <div className="flex min-h-screen flex-col bg-background text-text w-full">
      <main className="flex-1 p-2 flex flex-col w-full">
        <div className="container mx-auto">
          <div className="grid grid-cols-1 md:grid-cols-1 gap-2 w-full">
            <Card className="bg-background border border-[#9945FF]/20">
              <CardHeader>
                <CardTitle className="text-text">NFTs</CardTitle>
              </CardHeader>
              <CardContent>
                <NFTComponent />
              </CardContent>
            </Card>
          </div>
        </div>
      </main>
    </div>
  );
}

export default function NFTPage() {
  return <NFTContent />;
}
